import { toast } from '@pyreon/toast'

export async function api<T>(path: string): Promise<T> {
  const res = await fetch(path)
  if (!res.ok) {
    toast.error(`Request failed (${res.status})`, {
      description: path,
      // a retry that fails toasts again; it does not hand data back to the first caller
      action: { label: 'Retry', onClick: ({ dismiss }) => { dismiss(); api(path).catch(() => {}) } },
    })
    throw new Error(`[app] ${path} → ${res.status}`)
  }
  return res.json() as Promise<T>
}

function removeTask(task: Task) {
  tasks.update((ts) => ts.filter((t) => t.id !== task.id))
  let undone = false
  toast('Task deleted', {
    duration: 5000,
    action: {
      label: 'Undo',
      onClick: ({ dismiss }) => {
        undone = true
        tasks.update((ts) => [...ts, task])
        dismiss()
      },
    },
    onDismiss: () => { if (!undone) void deleteOnServer(task.id) },
  })
}
